     "To maintain high safety standards, we must occasionally delay or cancel a {5}. You can obtain the most up-to-date information at Gunterair.de, on the Gunter Air app, or on an information screen at the airport. Please provide your mobile number or e-mail address at check-in to receive status updates. If you booked through a travel agency, {6} sure that we have your correct contact information. Members of Gunter Air Advantage can add their contact information to their account. It will then be added {7} to each booking. {8}."
