     "In the Lansing plant, you {5} to Benjamin Simmons, plant manager. Your main responsibility will be to ensure that all our products meet quality standards. Please contact Benjamin as soon as possible to discuss your specific assignments.",
     "In addition, I encourage you to complete any unfinished business in your current job and help train your {6} before you leave your position at the end of March.",
