     "Zachary Morrison, president of Humantech Software, told reporters at the press conference that he was optimistic about the Ultrasys's success and hopeful that it will boost Humantech Software's image overall. Mr. Morrison noted that, in the same period, sales of Humantech's other game software for Ultrasys {12} as well.",
     "Humantech Software now accounts for 30 percent of the computer game market worldwide. Mr. Morrison expects Humantech to claim an even higher market share by the end of the year."
