     "Employees are entitled to twenty days of paid leave annually. A leave application form must be submitted in writing at least two weeks {13} of the intended dates. Leave requests require a supervisor's written approval. {14}. If you require time off on short notice, notify your supervisor and obtain verbal approval to use leave time. Remember to complete your request form when you return to the {15}. Any balance of leave time not taken during the current year must be used within the first six months of the following year or it will be forfeited. In such situations, the employer may use discretion to provide {16} in other ways."
