     "I received the customer-feedback report from our consultant. It took some time, but I have just finished {1} it. Based on many of the comments we received, I believe that Quality Breads should publish the ingredients used in our bread, cakes, and pastries. Although small retail {2} are not required to provide this information, it would help customers make informed choices. We have always insisted on the {3} quality ingredients, so there is no reason to withhold this information. {4}.",
